var o=`0583-ichlekli`;var i=`world-0583`;var t=`TM`;var l=`central-asia`;var a=4;var r=90;var s={en:`Ichlekli`,ua:`Ічлеклі`};var u={en:`A traditional dish from Turkmenistan, centered on all-purpose flour, ground lamb, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туркменістан. Основні складники: пшеничне борошно універсальне, фарш з ягнятини, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 16 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 16 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:16,i:[[`all-purpose-flour`,480,`g`],[`water`,210,`ml`],[`sunflower-oil`,40,`ml`],[`table-salt`,7,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:13,i:[[`ground-lamb`,520,`g`],[`yellow-onion`,230,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:13,i:[]},{en:`Roast in a preheated 190°C oven for about 48 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 48 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:48,i:[]}];var g={slug:o,id:i,country:`TM`,region:l,servings:4,minutes:90,title:s,text:u,steps:d};export{t as country,g as default,i as id,r as minutes,l as region,a as servings,o as slug,d as steps,u as text,s as title};